import {stats,bossState,sharedStreak,shiftDay} from './game.js?v=8';
const xml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function weeklyRecap(state,demo=false){
 const b=bossState(state),a=stats(state.activities,state.me,state.today),ids=state.profiles.map(p=>p.id);
 const checks=state.activities.filter(x=>ids.includes(x.user_id)&&x.kind==='checkin'&&x.payload?.status==='success'&&x.day>=b.week&&x.day<=state.today);
 return{week:b.week,end:shiftDay(b.week,6),asOf:state.today,streak:a.current,shared:sharedStreak(state.activities,ids,state.today),damage:b.damage,max:b.max,combos:b.comboDays,checkins:checks.length,boss:b.names[b.index],defeated:b.damage>=b.max,demo};
}
export function recapSvg(data){
 const title=data.defeated?'A victory for the ages.':'Still climbing. Together.';
 const date=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});
 const tiles=[['YOUR CURRENT STREAK',`${data.streak} days`],['DUO BOSS DAMAGE',`${data.damage} / ${data.max}`],['TEAM COMBOS',String(data.combos)],['TEAM CHECK-INS',String(data.checkins)]];
 return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350"><defs><radialGradient id="sky"><stop stop-color="#3b4d32"/><stop offset="1" stop-color="#101912"/></radialGradient><linearGradient id="gold"><stop stop-color="#d7b168"/><stop offset="1" stop-color="#f1d9a1"/></linearGradient></defs><rect width="1080" height="1350" fill="#101912"/><rect x="22" y="22" width="1036" height="1306" rx="32" fill="url(#sky)" stroke="#e9c777" stroke-opacity=".3"/><rect x="46" y="46" width="988" height="1258" rx="20" fill="none" stroke="#e9c777" stroke-opacity=".12"/><g fill="#e9c777" opacity=".3">${Array.from({length:26},(_,i)=>`<circle cx="${70+i*83%940}" cy="${82+i*47%480}" r="${i%4===0?3:1.5}"/>`).join('')}</g><g fill="none" stroke="#e9c777" opacity=".14"><circle cx="540" cy="345" r="186"/><circle cx="540" cy="345" r="204" stroke-dasharray="3 18"/><path d="M70 520 240 385 370 478 540 298 745 475 890 386 1010 520"/></g><text x="540" y="125" text-anchor="middle" fill="#e9c777" font-family="Georgia,serif" font-size="32" letter-spacing="12">OLYMPUS</text><text x="540" y="174" text-anchor="middle" fill="#aab9a3" font-family="Arial,sans-serif" font-size="17" letter-spacing="4">${data.demo?'DEMO · SAMPLE PROGRESS':'TWO LEGENDS. ONE ASCENT.'}</text><g fill="none" stroke="url(#gold)" stroke-width="3"><path d="M405 398h270v18H405zM423 385h234v13H423M435 300h210v15H435M425 300l115-61 115 61z"/><path d="M450 318v64m45-64v64m45-64v64m45-64v64m45-64v64" stroke-width="12"/></g><path d="m550 248-26 40h20l-7 29 31-43h-20l16-26z" fill="#e9c777"/><text x="540" y="507" text-anchor="middle" fill="#e9c777" font-family="Arial,sans-serif" font-size="17" letter-spacing="5">${data.defeated?'THE WEEKLY VICTORY':'OUR WEEK SO FAR'}</text><text x="540" y="574" text-anchor="middle" fill="#f2efdf" font-family="Georgia,serif" font-size="51">${title}</text><text x="540" y="618" text-anchor="middle" fill="#aab9a3" font-family="Arial,sans-serif" font-size="20">${xml(date(data.week))} – ${xml(date(data.end))} · Progress through ${xml(date(data.asOf))}</text>${tiles.map(([label,value],i)=>{const x=95+i%2*460,y=673+Math.floor(i/2)*185;return `<rect x="${x}" y="${y}" width="430" height="155" rx="18" fill="#17271e" stroke="#e9c777" stroke-opacity=".16"/><text x="${x+28}" y="${y+40}" fill="#aab9a3" font-family="Arial,sans-serif" font-size="15" letter-spacing="2">${label}</text><text x="${x+28}" y="${y+109}" fill="#eed59b" font-family="Georgia,serif" font-size="51">${xml(value)}</text>`}).join('')}<text x="540" y="1098" text-anchor="middle" fill="#e9c777" font-family="Arial,sans-serif" font-size="20">${xml(data.boss)}</text><rect x="175" y="1120" width="730" height="7" rx="4" fill="#ffffff12"/><rect x="175" y="1120" width="${Math.max(0,Math.min(730,730*data.damage/data.max))}" height="7" rx="4" fill="#e9c777"/><text x="540" y="1195" text-anchor="middle" fill="#aab9a3" font-family="Georgia,serif" font-size="25">One day at a time. A little stronger together.</text><text x="540" y="1250" text-anchor="middle" fill="#80927a" font-family="Arial,sans-serif" font-size="17">Made in OLYMPUS · Your climb. Your companion.</text></svg>`;
}
let dispose=()=>{};
export function closeWeeklyRecap(){dispose();dispose=()=>{}}
export function openWeeklyRecap({state,demo=false,showModal}){
 closeWeeklyRecap();const data=weeklyRecap(state,demo),svg=recapSvg(data),urls=[],controller=new AbortController();let file=null;
 const svgUrl=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));urls.push(svgUrl);
 showModal(`<div class="eyebrow">YOUR WEEKLY CARD</div><h2>${data.defeated?'A victory worth keeping.':'Your ascent, so far.'}</h2><p>No names, private notes, or challenge details appear on this card. You choose where to share it.</p><img class="recap-preview" src="${svgUrl}" alt="Weekly OLYMPUS card: ${data.streak}-day streak, ${data.damage} boss damage, ${data.combos} team combos and ${data.checkins} team check-ins"><div class="recap-actions"><button class="btn primary" data-recap-share disabled>Preparing image…</button><a class="btn" data-recap-save hidden>Save PNG ↓</a></div><p class="tiny recap-status" role="status">The image is generated on your device.</p>`);
 const dialog=document.querySelector('#modal'),preview=dialog.querySelector('.recap-preview'),share=dialog.querySelector('[data-recap-share]'),save=dialog.querySelector('[data-recap-save]'),status=dialog.querySelector('.recap-status');
 dispose=()=>{controller.abort();urls.forEach(url=>URL.revokeObjectURL(url))};dialog.addEventListener('close',closeWeeklyRecap,{once:true,signal:controller.signal});
 const image=new Image();image.onload=()=>{
  if(controller.signal.aborted)return;
  try{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Image export is unavailable');ctx.drawImage(image,0,0);
   canvas.toBlob(blob=>{if(controller.signal.aborted)return;if(!blob){status.textContent='Could not create the PNG. You can take a screenshot of the card.';share.textContent='Image unavailable';return}
    const name=`olympus-week-${data.week}.png`;file=new File([blob],name,{type:'image/png'});const pngUrl=URL.createObjectURL(blob);urls.push(pngUrl);preview.src=pngUrl;save.href=pngUrl;save.download=name;save.hidden=false;share.disabled=false;
    const canShare=typeof navigator.canShare==='function'&&navigator.canShare({files:[file]});share.textContent=canShare?'Share card ↗':'Download card ↓';status.textContent=data.demo?'Demo card · sample progress.':'Ready to share. No names or private notes included.';
   },'image/png');
  }catch{status.textContent='Image export is unavailable here. Take a screenshot of the card to keep it.';share.textContent='Image unavailable'}
 };
 image.onerror=()=>{if(!controller.signal.aborted){status.textContent='Could not prepare the card image. Try opening the recap again.';share.textContent='Image unavailable'}};image.src=svgUrl;
 share.addEventListener('click',()=>{if(!file)return;if(navigator.canShare?.({files:[file]})&&navigator.share){navigator.share({files:[file],title:'Our week in OLYMPUS'}).then(()=>{if(!controller.signal.aborted)status.textContent='Your card was shared.'}).catch(error=>{if(!controller.signal.aborted&&error.name!=='AbortError')status.textContent='Sharing is unavailable here. Use Save PNG instead.'})}else save.click()},{signal:controller.signal});
}
